#!/usr/bin/env node
/**
 * Claude Code adapter generator (DHI-526).
 * Reads adapters/claude/rule-map.yaml and writes a single root CLAUDE.md
 * from core .ai/rules sources (H2 section per mapped rule). Zero npm dependencies.
 *
 * Usage (repo root):
 *   node adapters/claude/generate.mjs
 *   node adapters/claude/generate.mjs --out /path/to/out
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const GENERATED_MARKER =
  "<!-- GENERATED by adapters/claude/generate.mjs — do not edit; re-run the generator -->";

/**
 * The How-to section hardcodes `.ai/...` paths that only resolve when this
 * repo IS the consumer root (self-host). Consumer installs vendor the
 * framework elsewhere (`vendor/agent-collections/`, or an out-of-tree
 * `AGENT_COLLECTIONS_HOME` in `local` mode), so every `.ai/...` reference
 * must be prefixed with the resolved framework location (frameworkPrefix
 * empty => self-host, unprefixed paths — see F11 in
 * docs/specs/claude-code-setup/claude-code-setup.research.md).
 */
function buildHowToSection(frameworkPrefix) {
  const withPrefix = (relPath) =>
    frameworkPrefix ? `${frameworkPrefix}/${relPath}` : relPath;

  return `## How to use prompts and skills

- Load public prompts by stable id under \`${withPrefix(".ai/prompts/public/")}\` (e.g. \`eversis-implement\`).
- Load internal / EM-routed prompts under \`${withPrefix(".ai/prompts/internal/")}\` when the orchestration flow requires them.
- Resolve skills via MCP (\`eversis_skills_get\` / \`eversis_skills_list\`) when available; otherwise read \`${withPrefix(".ai/skills/<id>/SKILL.md")}\`.
- Do **not** expect \`.cursor/commands\` or Cursor \`@\` attachment as the only entry — those are Cursor-channel packaging.
- Prefer backend / system-layer trees for CLI work; do **not** load Cursor-specific packaging (\`.cursor/rules/*.mdc\`, slash commands) for standards — this file is the Claude Code instruction surface.
- Full ignore-file / monorepo path isolation (\`.claudeignore\`, \`claudeMdExcludes\`) is **deferred** to DHI-528–530; until then, stay in the relevant package tree and avoid unrelated frontend/tool config when possible.
`;
}

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ADAPTER_DIR = __dirname;
const MAP_PATH = path.join(ADAPTER_DIR, "rule-map.yaml");
const CURSOR_MAP_PATH = path.join(ADAPTER_DIR, "..", "cursor", "rule-map.yaml");
const SCOPED_RULES_DIR_REL = ".claude/rules";

function fail(message) {
  console.error(`error: ${message}`);
  process.exit(1);
}

function findRepoRoot(startDir) {
  let dir = startDir;
  for (;;) {
    if (
      fs.existsSync(path.join(dir, ".ai")) &&
      fs.existsSync(path.join(dir, "adapters"))
    ) {
      return dir;
    }
    const parent = path.dirname(dir);
    if (parent === dir) {
      fail(
        "could not find repository root (expected .ai/ and adapters/). Run from repo root.",
      );
    }
    dir = parent;
  }
}

/**
 * --framework-prefix is a documentation token, not always a real filesystem
 * path — in `local` vendor mode it is the literal string
 * `${AGENT_COLLECTIONS_HOME}` (a Claude Code env-var reference), which has
 * no ".." segments and isn't absolute, so it safely passes the same checks
 * a real repo-relative path would (see assertSafeRepoRelative below, used
 * for rule `source` values).
 */
function assertSafeFrameworkPrefix(value) {
  if (value.startsWith("/")) {
    fail(`--framework-prefix must not be an absolute path: ${value}`);
  }
  if (value.split("/").some((segment) => segment === "..")) {
    fail(`--framework-prefix must not escape the target root: ${value}`);
  }
  return value.replace(/\/+$/, "");
}

function parseArgs(argv) {
  let outRoot = null;
  let frameworkPrefix = "";
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--out") {
      const next = argv[i + 1];
      if (!next || next.startsWith("-")) {
        fail("--out requires a directory path");
      }
      outRoot = path.resolve(next);
      i++;
      continue;
    }
    if (arg === "--framework-prefix") {
      const next = argv[i + 1];
      if (!next || next.startsWith("-")) {
        fail("--framework-prefix requires a value");
      }
      frameworkPrefix = assertSafeFrameworkPrefix(next);
      i++;
      continue;
    }
    if (arg === "--help" || arg === "-h") {
      console.log(
        "Usage: node adapters/claude/generate.mjs [--out <dir>] [--framework-prefix <path>]\n" +
          "  Default: write CLAUDE.md at the repository root.\n" +
          "  --out: write CLAUDE.md under <dir>.\n" +
          "  --framework-prefix: prepend <path> to every .ai/... reference in the\n" +
          "    How-to section (e.g. vendor/agent-collections, or the literal token\n" +
          "    ${AGENT_COLLECTIONS_HOME} in local vendor mode). Empty = self-host.",
      );
      process.exit(0);
    }
    fail(`unknown argument: ${arg}`);
  }
  return { outRoot, frameworkPrefix };
}

function stripQuotes(value) {
  if (
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"))
  ) {
    return value.slice(1, -1);
  }
  return value;
}

function parseScalar(raw) {
  const value = raw.trim();
  if (value === "true") return true;
  if (value === "false") return false;
  if (value === "[]") return [];
  if (/^-?\d+$/.test(value)) return Number(value);
  return stripQuotes(value);
}

/**
 * Constrained YAML parser for Claude rule-map.yaml shape only.
 * Supports: version, rules[] with scalar keys (id, source).
 */
function parseRuleMapYaml(text) {
  const lines = text.split(/\r?\n/);
  const doc = { version: null, rules: [] };
  let currentRule = null;

  for (let i = 0; i < lines.length; i++) {
    const rawLine = lines[i];
    const line = rawLine.replace(/\s+#.*$/, "");
    if (!line.trim() || line.trim().startsWith("#")) continue;

    const indent = line.match(/^ */)[0].length;
    const trimmed = line.trim();

    if (indent === 0 && trimmed.startsWith("version:")) {
      doc.version = parseScalar(trimmed.slice("version:".length));
      continue;
    }

    if (indent === 0 && trimmed === "rules:") {
      continue;
    }

    if (indent === 2 && trimmed.startsWith("- ")) {
      currentRule = {};
      doc.rules.push(currentRule);
      const rest = trimmed.slice(2).trim();
      if (rest.includes(":")) {
        const idx = rest.indexOf(":");
        const key = rest.slice(0, idx).trim();
        const val = rest.slice(idx + 1).trim();
        if (val !== "") {
          currentRule[key] = parseScalar(val);
        }
      }
      continue;
    }

    if (!currentRule) {
      fail(`unexpected line ${i + 1}: ${rawLine}`);
    }

    if (indent === 4 && trimmed.includes(":")) {
      const idx = trimmed.indexOf(":");
      const key = trimmed.slice(0, idx).trim();
      const val = trimmed.slice(idx + 1).trim();
      currentRule[key] = parseScalar(val);
      continue;
    }

    fail(`unexpected line ${i + 1}: ${rawLine}`);
  }

  return doc;
}

/**
 * Reads only `id` and `globs` from adapters/cursor/rule-map.yaml — the
 * Cursor map is the single source of truth for which rules are glob-scoped
 * (Cursor packaging fields like `alwaysApply`/`description`/`output` are
 * intentionally ignored here, not re-validated).
 */
function parseCursorGlobsMap(text) {
  const lines = text.split(/\r?\n/);
  const byId = new Map();
  let currentId = null;
  let currentGlobs = null;
  let inGlobs = false;

  const flush = () => {
    if (currentId) byId.set(currentId, currentGlobs ?? []);
  };

  for (const rawLine of lines) {
    const line = rawLine.replace(/\s+#.*$/, "");
    if (!line.trim() || line.trim().startsWith("#")) continue;

    const indent = line.match(/^ */)[0].length;
    const trimmed = line.trim();

    if (indent === 2 && trimmed.startsWith("- ")) {
      flush();
      currentId = null;
      currentGlobs = null;
      inGlobs = false;
      const rest = trimmed.slice(2).trim();
      if (rest.startsWith("id:")) {
        currentId = stripQuotes(rest.slice("id:".length).trim());
      }
      continue;
    }

    if (indent === 4 && trimmed.startsWith("id:")) {
      currentId = stripQuotes(trimmed.slice("id:".length).trim());
      inGlobs = false;
      continue;
    }

    if (indent === 4 && trimmed.startsWith("globs:")) {
      const inline = trimmed.slice("globs:".length).trim();
      if (inline === "[]" || inline === "") {
        currentGlobs = [];
        inGlobs = inline === "";
      } else {
        currentGlobs = [stripQuotes(inline)];
        inGlobs = false;
      }
      continue;
    }

    if (inGlobs && indent >= 6 && trimmed.startsWith("- ")) {
      currentGlobs.push(stripQuotes(trimmed.slice(2).trim()));
      continue;
    }

    if (indent === 4) {
      inGlobs = false;
    }
  }
  flush();

  return byId;
}

function loadCursorGlobsById(repoRoot) {
  if (!fs.existsSync(CURSOR_MAP_PATH)) {
    return new Map();
  }
  return parseCursorGlobsMap(fs.readFileSync(CURSOR_MAP_PATH, "utf8"));
}

function assertSafeRepoRelative(relPath, label) {
  if (!relPath || typeof relPath !== "string") {
    fail(`${label} must be a non-empty string`);
  }
  if (path.isAbsolute(relPath)) {
    fail(`${label} must be repo-relative (got absolute path): ${relPath}`);
  }
  const normalized = path.normalize(relPath);
  if (normalized.startsWith("..") || path.isAbsolute(normalized)) {
    fail(`${label} escapes repository root: ${relPath}`);
  }
  return normalized.split(path.sep).join("/");
}

function validateRule(rule, index) {
  const prefix = `rules[${index}]`;
  for (const key of ["id", "source"]) {
    if (rule[key] === undefined || rule[key] === null || rule[key] === "") {
      fail(`${prefix}: missing required field "${key}"`);
    }
  }
  rule.source = assertSafeRepoRelative(String(rule.source), `${prefix}.source`);
  for (const banned of ["globs", "alwaysApply", "description", "output"]) {
    if (Object.prototype.hasOwnProperty.call(rule, banned)) {
      fail(
        `${prefix} (${rule.id}): field "${banned}" is Cursor packaging — omit from Claude rule-map`,
      );
    }
  }
}

function resolveClaudeMdPath(repoRoot, outRoot) {
  if (!outRoot) {
    return path.join(repoRoot, "CLAUDE.md");
  }
  return path.join(outRoot, "CLAUDE.md");
}

function resolveOutputPath(repoRoot, outRoot, outputRel) {
  if (!outRoot) {
    return path.join(repoRoot, outputRel);
  }
  return path.join(outRoot, outputRel);
}

/**
 * `.claude/rules/*.md` frontmatter equivalent of Cursor's `globs:` — a
 * `paths:` array scopes the rule to matching files instead of loading it
 * every session (closes F6 in
 * docs/specs/claude-code-setup/claude-code-setup.research.md).
 */
function buildScopedRuleFrontMatter(paths) {
  const lines = ["---", "paths:"];
  for (const p of paths) {
    lines.push(`  - ${JSON.stringify(String(p))}`);
  }
  lines.push("---");
  return lines.join("\n");
}

function writeScopedRule(repoRoot, outRoot, rule, paths) {
  const sourceAbs = path.join(repoRoot, rule.source);
  if (!fs.existsSync(sourceAbs)) {
    fail(`source not found for ${rule.id}: ${rule.source}`);
  }
  const body = fs.readFileSync(sourceAbs, "utf8").replace(/^\uFEFF/, "");
  const content = `${buildScopedRuleFrontMatter(paths)}\n${GENERATED_MARKER}\n\n${body.replace(/\s+$/, "")}\n`;

  const outputRel = path.posix.join(SCOPED_RULES_DIR_REL, `${rule.id}.md`);
  const destAbs = resolveOutputPath(repoRoot, outRoot, outputRel);
  fs.mkdirSync(path.dirname(destAbs), { recursive: true });

  try {
    fs.lstatSync(destAbs);
    fs.unlinkSync(destAbs);
  } catch (err) {
    if (err.code !== "ENOENT") throw err;
  }

  fs.writeFileSync(destAbs, content, "utf8");
  return destAbs;
}

function cleanupOrphanScopedRules(repoRoot, outRoot, keepIds) {
  const dir = resolveOutputPath(repoRoot, outRoot, SCOPED_RULES_DIR_REL);
  if (!fs.existsSync(dir)) return [];

  const removed = [];
  for (const name of fs.readdirSync(dir)) {
    if (!/^eversis-.*\.md$/.test(name)) continue;
    const id = name.replace(/\.md$/, "");
    const abs = path.join(dir, name);
    let text = "";
    try {
      text = fs.readFileSync(abs, "utf8");
    } catch {
      continue;
    }
    if (!text.includes(GENERATED_MARKER)) continue;
    if (keepIds.has(id)) continue;
    fs.unlinkSync(abs);
    removed.push(abs);
  }
  return removed;
}

function buildClaudeMarkdown(repoRoot, rules, frameworkPrefix) {
  const parts = [
    "# Agent Collections (Claude Code)",
    "",
    GENERATED_MARKER,
    "",
    buildHowToSection(frameworkPrefix).trimEnd(),
    "",
  ];

  for (const rule of rules) {
    const sourceAbs = path.join(repoRoot, rule.source);
    if (!fs.existsSync(sourceAbs)) {
      fail(`source not found for ${rule.id}: ${rule.source}`);
    }
    const body = fs.readFileSync(sourceAbs, "utf8").replace(/^\uFEFF/, "");
    parts.push(`## ${rule.id}`);
    parts.push("");
    parts.push(body.replace(/\s+$/, ""));
    parts.push("");
  }

  return `${parts.join("\n").replace(/\s+$/, "")}\n`;
}

function writeClaudeMd(repoRoot, outRoot, rules, frameworkPrefix) {
  const content = buildClaudeMarkdown(repoRoot, rules, frameworkPrefix);
  const destAbs = resolveClaudeMdPath(repoRoot, outRoot);
  fs.mkdirSync(path.dirname(destAbs), { recursive: true });

  try {
    fs.lstatSync(destAbs);
    fs.unlinkSync(destAbs);
  } catch (err) {
    if (err.code !== "ENOENT") throw err;
  }

  fs.writeFileSync(destAbs, content, "utf8");
  return destAbs;
}

function main() {
  const { outRoot, frameworkPrefix } = parseArgs(process.argv.slice(2));
  const repoRoot = findRepoRoot(process.cwd());

  if (!fs.existsSync(MAP_PATH)) {
    fail(`rule map not found: ${MAP_PATH}`);
  }

  const map = parseRuleMapYaml(fs.readFileSync(MAP_PATH, "utf8"));
  if (map.version !== 1) {
    fail(`unsupported rule-map version: ${map.version} (expected 1)`);
  }
  if (!Array.isArray(map.rules) || map.rules.length === 0) {
    fail("rule-map has no rules");
  }

  map.rules.forEach(validateRule);

  const globsById = loadCursorGlobsById(repoRoot);
  const inlineRules = [];
  const scopedRules = [];
  for (const rule of map.rules) {
    const globs = globsById.get(rule.id) ?? [];
    if (globs.length > 0) {
      scopedRules.push({ rule, globs });
    } else {
      inlineRules.push(rule);
    }
  }

  const dest = writeClaudeMd(repoRoot, outRoot, inlineRules, frameworkPrefix);
  console.log(`generated Claude Code instructions:`);
  console.log(`  ${path.relative(process.cwd(), dest) || dest}`);
  console.log(`  (${inlineRules.length} rule section(s))`);

  const keepScopedIds = new Set(scopedRules.map(({ rule }) => rule.id));
  const writtenScoped = scopedRules.map(({ rule, globs }) =>
    writeScopedRule(repoRoot, outRoot, rule, globs),
  );
  if (writtenScoped.length > 0) {
    console.log(`generated ${writtenScoped.length} scoped Claude rule(s):`);
    for (const p of writtenScoped) {
      console.log(`  ${path.relative(process.cwd(), p) || p}`);
    }
  }
  const removedScoped = cleanupOrphanScopedRules(
    repoRoot,
    outRoot,
    keepScopedIds,
  );
  if (removedScoped.length > 0) {
    console.log(`removed ${removedScoped.length} orphan scoped rule(s):`);
    for (const p of removedScoped) {
      console.log(`  ${path.relative(process.cwd(), p) || p}`);
    }
  }
}

main();
